'use strict';
const STOPS=[{id:'bowery',time:'10:00 AM',focus:'Buyer check-in',number:'01'},{id:'borough',time:'12:30 PM',focus:'Flower positioning & price',number:'02'},{id:'hudson',time:'3:00 PM',focus:'New account introduction',number:'03'}];
let debriefs=[];try{debriefs=JSON.parse(localStorage.getItem('quickhits-debriefs-v1')||'[]');if(!Array.isArray(debriefs))debriefs=[];}catch{}
const morningBrief=()=>`Morning, Harry. Let’s get you ready for the day. You’ve got three customer conversations in this September 25 demo plan. First up, Bowery Green at ten. Two listings are missing from the sample menu, so check in with Jordan on availability and the assortment. Then it’s Borough Bloom at twelve thirty. Have that flower pricing comparison handy. At three, you’ve got an introduction with Hudson Valley Collective. A good chance to learn what the buyer is looking for. Those appointments and account updates are demo examples. For market context, the territory briefing includes a September 3 New York OCM update on regional market data. Use it to prepare questions, then confirm the buyer’s own priorities. You’ll find the source in your territory briefing. After each visit, take a moment to capture what happened and who’s doing what next. We’ll pull it together for your field report.`;
function home(){const next=STOPS.find(s=>!debriefs.some(d=>d.account===s.id))||STOPS[0],a=ACCOUNTS.find(a=>a.id===next.id);return `<div class="rep-dayline"><span>NEW YORK FIELD TEAM</span><span>FRIDAY, SEPTEMBER 25 · SAMPLE DAY</span></div><div class="rep-lead"><section class="morning-card"><div class="card-kicker">MORNING BRIEFING</div><h1>Today’s<br>briefing<span class="red-dot">.</span></h1><p class="page-subhead">Your stops, your priorities, and what’s worth knowing today.</p><p>Harry · 3 scheduled visits</p><div class="morning-controls"><button class="round-play" id="play-morning" aria-label="Listen to my morning brief">▶</button><div><strong>Listen to your morning brief</strong><span>Account context + territory headlines</span></div></div><div class="morning-bottom"><a href="#brief">Read the brief ↗</a><span>Betty’s Eddies / QUICKHITS</span></div><div id="audio-status" class="morning-audio" role="status"></div><button class="stop-morning" id="stop-morning">Stop audio</button></section>${appointmentSlider()}</div><section class="day-stops"><div class="rep-section-title"><div><span class="card-kicker">GOOGLE CALENDAR · DEMO</span><h2>Your calendar</h2></div><a href="#visits">View your visits ↗</a></div><div class="visit-grid">${STOPS.map(s=>stopCard(s)).join('')}</div></section><div class="rep-tool-links"><span>Account tools</span><a href="#accounts">All accounts</a><a href="#products">Competition Check</a><a href="#activity">Activity history</a></div>`;}
function stopCard(s){const a=ACCOUNTS.find(a=>a.id===s.id),done=debriefs.some(d=>d.account===s.id);return `<article class="visit-card"><div class="visit-card-top"><span>${s.time}</span>${badge(done?'Debrief saved':a.status,done?'':'blue')}</div><h3><a href="#appointment/${s.id}">${a.name}</a></h3><p>${s.focus}</p><p class="calendar-meta">${calendarMeta(s.id)}</p><p class="fineprint">${esc(a.contact)} · ${esc(a.city)}<br>Google Calendar sample · Not synced</p><div class="visit-card-actions"><button class="text-button" data-prep="${a.id}">Before I go ↗</button><a href="#debrief/${a.id}">${done?'Edit recap':'Just left'} →</a></div></article>`;}
function visits(){return `${heading('YOUR SAMPLE FIELD PLAN','My visits','See who’s next and pick up where you left off. Demo appointments · Sep 25 · Calendar not connected.')}<div class="visit-grid">${STOPS.map(stopCard).join('')}</div><div class="rep-tool-links"><a href="#accounts">Browse all accounts ↗</a><a href="#activity">Rep notes & comments ↗</a><a href="#report">Review daily field report ↗</a></div>`;}
function readMorning(){return `${heading('MORNING BRIEF / SAMPLE DAY','Morning brief','A quick rundown before your first stop. September 25 edition · Demo appointments and sourced news.')}<div class="panel article morning-reading"><p>${esc(morningBrief())}</p><div class="briefing-actions"><button class="primary" id="play-morning">▶ Listen to the brief</button><button class="secondary" id="stop-morning">Stop audio</button><a href="#news" class="secondary">Read market sources ↗</a></div><p id="audio-status" role="status" class="fineprint">Set up playback while parked.</p></div>`;}
function debriefPage(id){const a=ACCOUNTS.find(a=>a.id===id);if(!a)return missing();const saved=debriefs.find(d=>d.account===id)||{};return `<a href="#visits" class="text-button">← Your visits</a>${heading('POST-VISIT CAPTURE', 'How’d it go?',a.name+' · What came up, what you agreed, and what happens next.')}<form id="debrief-form" class="panel debrief-form" data-account="${a.id}"><div class="debrief-context">${a.name}<span>Internal field report · saved on this browser</span></div>${readbackControls("debrief")}<label>What happened?<textarea id="meeting-outcome" name="outcome" required rows="3" maxlength="1600" placeholder="Buyer feedback, product interest, objections, confirmed outcomes…">${esc(saved.outcome||'')}</textarea></label><button type="button" class="secondary" data-dictate="meeting-outcome">Speak a note</button><p id="voice-status" class="fineprint" role="status">Type your notes, or speak and review the transcript before saving.</p>${mediaPanel(a.id)}<div class="debrief-row"><label>Where it stands<select name="result">${['Follow-up needed','Opportunity identified','Order confirmed by rep','No change','Visit did not happen'].map(x=>`<option ${saved.result===x?'selected':''}>${x}</option>`).join('')}</select></label><label>What’s next?<input id="meeting-action" name="action" required maxlength="240" value="${esc(saved.action||'')}" placeholder="e.g. Confirm availability with operations"></label></div><div class="debrief-row"><label>Who’s on it?<input name="owner" required maxlength="100" value="${esc(saved.owner||'Harry')}"></label><label>Due date<input name="due" type="date" required value="${esc(saved.due||'2026-09-28')}"></label></div><div class="briefing-actions"><button type="button" class="secondary" data-dictate="meeting-action" data-voice-label="🎙 Speak the next step">🎙 Speak the next step</button><button type="button" class="secondary" data-dictate="meeting-support" data-voice-label="🎙 Speak a team request">🎙 Speak a team request</button><button type="button" class="secondary" data-cancel-dictation>Stop recording</button></div><label>Need anything from the team? <span class="fineprint">Optional</span><textarea id="meeting-support" name="support" rows="2" maxlength="600" placeholder="What should your manager or team help with?">${esc(saved.support||'')}</textarea></label><p class="fineprint">Capture notes while parked. You can use your device’s keyboard dictation. “Order confirmed by rep” records your statement; it does not place or verify an order.</p><div class="briefing-actions"><button class="primary" type="submit">Save recap & next steps →</button><button type="button" class="secondary" id="email-debrief">Send Email</button></div></form>`;}
function reportText(){return `QUICKHITS — DAILY FIELD REPORT\nBetty’s Eddies demo | Harry | Sample day: September 25, 2026\nFor internal review — fictional accounts, rep-entered outcomes not independently verified\n\n${debriefs.length?debriefs.map(d=>{const a=ACCOUNTS.find(a=>a.id===d.account);return `${a?.name||d.account}\nOutcome: ${d.result}\nVisit summary: ${d.outcome}\nNext action: ${d.action}\nOwner: ${d.owner} | Due: ${d.due}\nManagement support: ${d.support||'None requested'}\n`;}).join('\n'):'No visit debriefs have been captured. Do not report planned visits as completed.\n'}\nPLANNED VISITS WITHOUT A DEBRIEF\n${STOPS.filter(s=>!debriefs.some(d=>d.account===s.id)).map(s=>ACCOUNTS.find(a=>a.id===s.id).name+' — outcome not recorded').join('\n')||'All sample stops have debriefs.'}\n\nReview facts, action owners and dates before sharing. No orders or messages have been sent by QuickHits.`;}
function reportPage(){let draft=reportText();try{draft=localStorage.getItem('betty-report-draft-v1')||draft}catch{}return `${accountViews('report')}${heading('DAILY FIELD REPORT','Daily Wrap','Bring the day together: visits, follow-ups, and what the team needs to know.')}<section class="panel report-panel"><div class="section-head"><h2>${debriefs.length} debriefs captured</h2><button class="text-button" id="rebuild-report">Rebuild from saved debriefs</button></div>${readbackControls("report")}<label for="report-draft">Internal review draft</label><textarea id="report-draft" rows="19">${esc(draft)}</textarea><div class="briefing-actions"><button class="primary" id="download-report">Download report ↓</button><button class="secondary" id="copy-report">Copy for internal post</button><button class="secondary" id="save-report">Save draft</button><button type="button" class="primary" id="email-report">Send Email</button></div><button type="button" class="secondary" id="download-media-report">Download report with photos & video ↓</button><label>Attach media to account<select id="report-media-account">${ACCOUNTS.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><div id="report-attachment-picker">${mediaPanel(ACCOUNTS[0].id)}</div>${mediaPanel("all",true)}<p class="fineprint" id="report-status" role="status">Nothing is sent automatically. Copying or downloading lets you review and share through your own team channel.</p></section>`;}
document.addEventListener('click',async e=>{const prep=e.target.closest('[data-prep]');if(prep){selectedAccount=prep.dataset.prep;messages=[];location.hash='ai';return;}if(e.target.closest('#play-morning'))speak(morningBrief());if(e.target.closest('#stop-morning'))stopAudio();if(e.target.closest('#rebuild-report')){document.getElementById('report-draft').value=reportText();document.getElementById('report-status').textContent='Draft rebuilt from saved debriefs. Previous edits replaced in this view; save to keep this version.';}if(e.target.closest('#save-report')){try{localStorage.setItem('betty-report-draft-v1',document.getElementById('report-draft').value);document.getElementById('report-status').textContent='Draft saved on this browser.';}catch{document.getElementById('report-status').textContent='Storage unavailable. Download your report to keep it.';}}if(e.target.closest('#copy-report')){try{await navigator.clipboard.writeText(document.getElementById('report-draft').value);document.getElementById('report-status').textContent='Copied. Ready to review and paste into your internal channel; not posted.';}catch{document.getElementById('report-status').textContent='Copy unavailable. Select the report text or download it.';}}if(e.target.closest('#download-report')){bettyDownloadText('Daily-Field-Report',document.getElementById('report-draft').value);document.getElementById('report-status').textContent='Report download requested. No message was sent.';}});
document.addEventListener('submit',e=>{if(e.target.id!=='debrief-form')return;e.preventDefault();const form=e.target,fields=new FormData(form),row={account:form.dataset.account,...Object.fromEntries(fields),savedAt:new Date().toISOString()};if(!row.outcome.trim()||!row.action.trim()||!row.owner.trim()){toast('Add an outcome, next action and owner.');return;}debriefs=debriefs.filter(d=>d.account!==row.account);debriefs.push(row);const noteId='debrief-'+row.account+'-'+Date.now();notes.unshift({id:noteId,account:row.account,type:row.result==='Visit did not happen'?'Follow-up':'Store visit',text:row.outcome+' Next action: '+row.action+'. Owner: '+row.owner+'. Due: '+row.due+(row.support?' Support needed: '+row.support:''),date:row.savedAt,author:'Harry',local:true});let stored=true;try{localStorage.setItem('quickhits-debriefs-v1',JSON.stringify(debriefs));localStorage.setItem('betty-demo-notes-v1',JSON.stringify(notes.filter(n=>n.local)))}catch{stored=false}location.hash='visits';toast(stored?'Debrief saved. Your next steps are ready for the field report.':'Saved for this session only. Download your report to keep it.');});

// Local visit attachments: files stay on this device, separate from OpenAI prompts.
function mediaPanel(account,readOnly=false){return `<section class="visit-media" data-media-account="${esc(account)}"><h3>${readOnly?'Photos & video for your report':'Photos & video'}</h3><p class="fineprint">${readOnly?'Included in the media report download.':'Attach shelf photos, displays, or a short clip to this account’s meeting notes.'} Saved on this browser only. Not posted or sent to AI.</p>${readOnly?'':`<label class="secondary media-picker">Add images or video<input type="file" data-media-input="${esc(account)}" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,video/webm,video/quicktime" multiple></label><p class="fineprint">Up to 8 files per account · 25 MB each. Use MP4 or WebM for the best video playback.</p>`}<p class="media-status fineprint" role="status"></p><div class="media-list">Loading attachments…</div></section>`;}
let mediaDBPromise=null,mediaURLs=[],mediaRenderVersion=0;
function mediaDB(){if(!mediaDBPromise)mediaDBPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('quickhits-visit-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('files',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>{mediaDBPromise=null;reject(Error('Attachment storage unavailable.'));};});return mediaDBPromise;}
async function mediaRows(){const db=await mediaDB();return new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not load attachments.'));});}
async function mediaWrite(records,remove=false){const db=await mediaDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite'),store=tx.objectStore('files');for(const row of records)remove?store.delete(row.id):store.put(row);tx.oncomplete=resolve;tx.onerror=()=>reject(Error('Could not save attachments. Browser storage may be full.'));tx.onabort=()=>reject(Error('Attachment save was cancelled.'));});}
async function hydrateMedia(){const version=++mediaRenderVersion;mediaURLs.forEach(URL.revokeObjectURL);mediaURLs=[];const panels=[...document.querySelectorAll('[data-media-account]')];if(!panels.length)return;try{const rows=await mediaRows();if(version!==mediaRenderVersion)return;for(const panel of panels){const filtered=rows.filter(r=>panel.dataset.mediaAccount==='all'||r.account===panel.dataset.mediaAccount);panel.querySelector('.media-list').innerHTML=filtered.length?filtered.map(r=>{const url=URL.createObjectURL(r.blob);mediaURLs.push(url);const preview=r.type.startsWith('image/')?`<img src="${url}" alt="${esc(r.name)}" loading="lazy">`:`<video src="${url}" controls preload="metadata"></video>`;return `<article class="media-card">${preview}<strong>${esc(r.name)}</strong><small>${esc(ACCOUNTS.find(a=>a.id===r.account)?.name||r.account)} · ${(r.blob.size/1048576).toFixed(1)} MB</small><a href="${url}" download="${esc(r.name)}">Download original</a>${panel.dataset.mediaAccount==='all'?'':`<button type="button" class="text-button" data-remove-media="${r.id}">Remove</button>`}</article>`;}).join(''):'<p class="fineprint">No attachments yet.</p>';}}catch(e){for(const p of panels)p.querySelector('.media-list').textContent=e.message;}}
const renderBeforeMedia=render;render=function(){renderBeforeMedia();hydrateMedia();};
let mediaSaving=false;
document.addEventListener('change',async e=>{const input=e.target.closest('[data-media-input]');if(!input)return;const panel=input.closest('[data-media-account]'),status=panel.querySelector('.media-status');if(mediaSaving){status.textContent='Wait for the current upload to finish.';return;}const files=[...input.files],allowed=['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime'];if(!files.length)return;mediaSaving=true;input.disabled=true;try{if(files.some(f=>!allowed.includes(f.type)||f.size>25*1048576||!f.size))throw Error('Choose images or video up to 25 MB each. Empty or unsupported files cannot be attached.');const rows=await mediaRows();if(rows.filter(r=>r.account===input.dataset.mediaInput).length+files.length>8)throw Error('Keep up to 8 attachments per account. Remove one before adding more.');status.textContent='Saving on this device…';await mediaWrite(files.map(f=>({id:crypto.randomUUID(),account:input.dataset.mediaInput,name:f.name,type:f.type,blob:f,createdAt:new Date().toISOString()})));await hydrateMedia();status.textContent='Attached to this account’s meeting notes and day wrap.';}catch(err){status.textContent=err.message;}finally{input.value='';input.disabled=false;mediaSaving=false;}});
function blobData(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read attachment.'));r.readAsDataURL(blob);});}
document.addEventListener('click',async e=>{const remove=e.target.closest('[data-remove-media]');if(remove){try{await mediaWrite([{id:remove.dataset.removeMedia}],true);await hydrateMedia();}catch(err){toast(err.message);}return;}if(!e.target.closest('#download-media-report'))return;const button=e.target.closest('button'),reportStatus=document.getElementById('report-status'),reportDraft=document.getElementById('report-draft').value;button.disabled=true;try{const rows=await mediaRows();let cards='';for(const r of rows){const src=await blobData(r.blob);cards+=`<article><h3>${esc(ACCOUNTS.find(a=>a.id===r.account)?.name||r.account)}</h3><p>${esc(r.name)}</p>${r.type.startsWith('image/')?`<img src="${src}" alt="${esc(r.name)}">`:`<video src="${src}" controls></video>`}<p><a href="${src}" download="${esc(r.name)}">Download original</a></p></article>`;}const doc='<!doctype html><html lang="en"><meta charset="utf-8"><title>QuickHits — Day wrap</title><style>body{font:16px system-ui;max-width:900px;margin:40px auto;padding:20px;color:#163c48}pre{white-space:pre-wrap;font:inherit;line-height:1.6}article{border-top:1px solid #ccc;margin-top:24px;padding-top:16px}img,video{max-width:100%;max-height:550px}</style><h1>QuickHits — Day wrap</h1><pre>'+esc(reportDraft)+'</pre><h2>Meeting attachments</h2><p>Account-linked media saved locally by the rep. Not evidence that a planned visit was completed.</p>'+cards+'</html>';const url=URL.createObjectURL(new Blob([doc],{type:'text/html'}));const a=document.createElement('a');a.href=url;a.download='QuickHits-Day-Wrap-With-Media.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);reportStatus.textContent='Report with attachments downloaded. Review it before sharing; nothing was posted.';}catch(err){reportStatus.textContent=err.message;}finally{button.disabled=false;}});

function readbackControls(kind){return '<div class="readback-controls"><button type="button" class="primary" data-readback="'+kind+'">▶ Read it to me</button><button type="button" class="secondary" data-stop-readback>■ Stop</button><span id="audio-status" class="fineprint" role="status">Listen to the current draft. Nothing is saved or sent to your team.</span></div>';}
function currentDebriefText(form){const f=new FormData(form),get=n=>String(f.get(n)||'').trim(),account=ACCOUNTS.find(a=>a.id===form.dataset.account);if(!get('outcome')&&!get('action')&&!get('support'))return '';return [account?.name+' — meeting notes.','What happened: '+(get('outcome')||'Not recorded.'),'Where it stands: '+get('result'),'Next step: '+(get('action')||'Not recorded.'),'Who’s on it: '+(get('owner')||'Not assigned.'),'Due date: '+(get('due')?new Date(get('due')+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}):'Not set.'),'Team support: '+(get('support')||'None noted.')].join('\n\n');}
document.addEventListener('click',e=>{if(e.target.closest('[data-stop-readback]')){stopListening();stopAudio();return;}const b=e.target.closest('[data-readback]');if(!b)return;const text=b.dataset.readback==='report'?document.getElementById('report-draft').value.trim():currentDebriefText(document.getElementById('debrief-form'));if(!text){audioStatus('Add a note first, then I can read it back.');return;}if(text.length>6000){deviceSpeak(text);}else{speak(text);}});

// Follow-ups derived from reviewed recaps, plus explicitly added tasks.
let manualFollowups=[],followupDone={},followupFilter='open';
try{const rows=JSON.parse(localStorage.getItem('quickhits-followups-v1')||'[]');if(Array.isArray(rows))manualFollowups=rows;const done=JSON.parse(localStorage.getItem('quickhits-followup-done-v1')||'{}');if(done&&typeof done==='object'&&!Array.isArray(done))followupDone=done;}catch{}
const DEMO_FOLLOWUPS=[
{id:'demo-fu-borough-comparison',account:'borough',action:'Send Sam the flower price comparison before the next reorder discussion.',owner:'Harry',due:'2026-10-06',waiting:false},
{id:'demo-fu-bowery-sellsheet',account:'bowery',action:'Send Jordan the updated pre-roll sell sheet and pack-size options.',owner:'Harry',due:'2026-09-26',waiting:false},
{id:'demo-fu-queens-gummies',account:'queens',action:'Call Casey to confirm which gummy options the team wants to review.',owner:'Harry',due:'2026-09-26',waiting:false},
{id:'demo-fu-buffalo-display',account:'buffalo',action:'Get the approved counter-display artwork for Jamie’s merchandising review.',owner:'Morgan · Marketing (demo)',due:'2026-09-28',waiting:true},
{id:'demo-fu-rochester-training',account:'rochester',action:'Get trainer availability for Drew’s floor-team education session.',owner:'Taylor · Brand education (demo)',due:'2026-09-28',waiting:true},
{id:'demo-fu-capital-training',account:'capital',action:'Confirm a date with Morgan for the pre-roll staff training.',owner:'Harry',due:'2026-09-29',waiting:false},
{id:'demo-fu-hudson-intro',account:'hudson',action:'Draft an opening assortment for Taylor based on the introductory conversation.',owner:'Harry',due:'2026-09-30',waiting:false}
].map(row=>({...row,source:'Demo Salesforce task · synthetic'}));
function followupRows(){const derived=debriefs.flatMap(d=>{const rows=[];if(d.action?.trim())rows.push({id:'recap:'+JSON.stringify([d.account,d.action,d.owner,d.due]),account:d.account,action:d.action,owner:d.owner,due:d.due,waiting:false,source:'Saved meeting recap'});if(d.support?.trim())rows.push({id:'support:'+JSON.stringify([d.account,d.support,d.due]),account:d.account,action:d.support,owner:'Team · owner not assigned',due:d.due,waiting:true,source:'Team request from recap'});return rows;});return [...DEMO_FOLLOWUPS,...derived,...manualFollowups].map(row=>({...row,done:!!followupDone[row.id]})).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));}
function followupToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function followupBucket(row,today){if(row.done)return 'Done';if(row.waiting)return 'Waiting on the team';if(!row.due)return 'No date yet';if(row.due<today)return 'Overdue';if(row.due===today)return 'Due today';return 'Coming up';}
function followupsPage(){const rows=followupRows(),today=followupToday(),open=rows.filter(r=>!r.done);const visible=rows.filter(r=>followupFilter==='all'||(followupFilter==='done'?r.done:followupFilter==='waiting'?r.waiting&&!r.done:followupFilter==='today'?!r.done&&r.due&&r.due<=today:!r.done));const groups=['Overdue','Due today','Waiting on the team','Coming up','No date yet','Done'];return `${accountViews('followups')}${heading('KEEP IT MOVING','My Follow-Ups','The promises, callbacks, and next steps that keep business rolling.')}<div class="followup-summary"><span><b>${open.length}</b> open</span><span><b>${open.filter(r=>r.due&&r.due<=today).length}</b> due or overdue</span><span><b>${open.filter(r=>r.waiting).length}</b> waiting on the team</span></div><p class="fineprint">Dates use New York time · ${esc(today)}. Includes 7 synthetic Salesforce tasks dated Sep 25–30, 2026, plus saved meeting recaps and tasks you add. Demo accounts · Saved on this browser. No reminders or messages are sent.</p><div class="toolbar"><label for="followup-filter">Show</label><select id="followup-filter">${[['open','All open'],['today','Due today & overdue'],['waiting','Waiting on the team'],['done','Done'],['all','Everything']].map(([v,t])=>`<option value="${v}" ${v===followupFilter?'selected':''}>${t}</option>`).join('')}</select><a class="secondary" href="#report">Day wrap ↗</a></div>${visible.length?groups.map(group=>{const matching=visible.filter(r=>followupBucket(r,today)===group);return matching.length?`<section class="followup-group"><h2>${group}</h2>${matching.map(followupCard).join('')}</section>`:'';}).join(''):'<div class="panel empty">Nothing here right now. Add a follow-up below, or save the next step in Take Notes.</div>'}<details class="panel followup-add"><summary>Add a follow-up</summary><form id="followup-form"><label>Account<select name="account">${ACCOUNTS.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><label>What needs to happen?<input name="action" required maxlength="240" placeholder="Send pricing, check availability, call the buyer…"></label><div class="debrief-row"><label>Who’s on it?<input name="owner" required maxlength="100" value="Harry"></label><label>Due date<input type="date" name="due" required value="${today}"></label></div><label>Where it stands<select name="state"><option value="open">Ready to do</option><option value="waiting">Waiting on the team</option></select></label><button class="primary" type="submit">Add follow-up</button><p class="fineprint">This adds a task only. It doesn’t send a request to anyone.</p></form></details>`;}
function followupCard(row){const a=ACCOUNTS.find(a=>a.id===row.account);return `<article class="panel followup-card"><div><a href="#accounts/${esc(row.account)}">${esc(a?.name||row.account)}</a><h3>${esc(row.action)}</h3><p>${esc(row.owner)} · Due ${row.due?esc(new Date(row.due+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})):'not set'}</p><small>${esc(row.source||'Added by rep')}${row.done?' · Completed':''}</small></div><div class="followup-actions"><button type="button" class="${row.done?'secondary':'primary'}" data-followup-toggle="${esc(row.id)}">${row.done?'Reopen':'Mark done'}</button>${row.source?.includes('recap')?`<a class="text-button" href="#debrief/${esc(row.account)}">View / edit recap</a>`:''}</div></article>`;}
document.addEventListener('change',e=>{if(e.target.id==='followup-filter'){followupFilter=e.target.value;render();}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-followup-toggle]');if(!b)return;const id=b.dataset.followupToggle,next={...followupDone};if(next[id])delete next[id];else next[id]=new Date().toISOString();try{localStorage.setItem('quickhits-followup-done-v1',JSON.stringify(next));followupDone=next;render();toast(next[id]?'Marked done. Find it under Done to reopen.':'Follow-up reopened.');}catch{toast('Could not save that change. Browser storage may be full.');}});
document.addEventListener('submit',e=>{if(e.target.id!=='followup-form')return;e.preventDefault();const f=new FormData(e.target),action=String(f.get('action')).trim(),owner=String(f.get('owner')).trim();if(!action||!owner){toast('Add a next step and an owner.');return;}const row={id:'manual:'+crypto.randomUUID(),account:String(f.get('account')),action,owner,due:String(f.get('due')),waiting:f.get('state')==='waiting',source:'Added by rep'},next=[...manualFollowups,row];try{localStorage.setItem('quickhits-followups-v1',JSON.stringify(next));manualFollowups=next;followupFilter='open';render();toast('Follow-up added.');}catch{toast('Could not save. Your form is still here.');}});

const DEMO_SF_OPPORTUNITIES=[{id:'SF-DEMO-001',account:'bowery',title:'Flower & pre-roll reorder',stage:'Proposal',value:4200,close:'2026-09-30',next:'Confirm availability before sending the reorder proposal.'},{id:'SF-DEMO-002',account:'borough',title:'Expanded flower assortment',stage:'Negotiation',value:6500,close:'2026-10-02',next:'Review the comparison with Sam and confirm the proposed assortment.'},{id:'SF-DEMO-003',account:'hudson',title:'Opening assortment',stage:'Qualification',value:7800,close:'2026-10-09',next:'Learn the buyer’s category priorities and agree on a starting assortment.'}];
function calendarMeta(id){return ({bowery:'10:00–10:45 AM · In-store visit',borough:'12:30–1:15 PM · Buyer meeting',hudson:'3:00–3:30 PM · Intro video call'})[id]||'Sample appointment';}
function demoSourceStrip(){return '<div class="demo-source-strip"><span>Google Calendar <b>DEMO DATA</b></span><span>Salesforce <b>DEMO DATA</b></span><small>Illustrative September 25 schedule and CRM records. No accounts connected or data synced.</small></div>';}
function salesforceDashboard(){const total=DEMO_SF_OPPORTUNITIES.reduce((sum,o)=>sum+o.value,0);return '<section class="sf-dashboard"><div class="rep-section-title"><div><span class="card-kicker">SALESFORCE · SYNTHETIC SNAPSHOT</span><h2>Your pipeline</h2></div><a href="#followups">My follow-ups ↗</a></div><div class="sf-metrics"><div><strong>'+money(total)+'</strong><span>Open pipeline · unweighted</span></div><div><strong>'+DEMO_SF_OPPORTUNITIES.length+'</strong><span>Open opportunities</span></div><div><strong>'+ACCOUNTS.filter(a=>a.status==='Active').length+'</strong><span>Active demo accounts</span></div></div><p class="fineprint">Illustrative opportunity amounts, not confirmed orders or booked sales. Owner: Harry · Sample snapshot: Oct 6, 2026.</p><div class="sf-opportunities">'+DEMO_SF_OPPORTUNITIES.map(o=>{const a=ACCOUNTS.find(a=>a.id===o.account);return '<article class="panel sf-opportunity"><div class="section-head"><a href="#accounts/'+a.id+'">'+esc(a.name)+'</a>'+badge(o.stage,'blue')+'</div><h3>'+esc(o.title)+'</h3><p class="sf-value">'+money(o.value)+'</p><p class="fineprint">Target close '+esc(new Date(o.close+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}))+'</p><details><summary>Next step & CRM details</summary><p>'+esc(o.next)+'</p><small>'+o.id+' · Harry · Synthetic Salesforce record</small></details><button type="button" class="secondary" data-prep="'+a.id+'">Prep this account →</button></article>';}).join('')+'</div></section>';}

function hotProspects(){const prospects=ACCOUNTS.filter(a=>a.status==='Prospect');return '<section class="hot-prospects"><div class="rep-section-title"><div><span class="card-kicker">NEW BUSINESS · DEMO</span><h2>Hot Prospects</h2></div><a href="#accounts">Explore accounts ↗</a></div><p class="fineprint">Fictional prospects for the Betty’s Eddies demo territory—not existing customers or verified leads. “Hot” is a demo spotlight, not a scored buying signal.</p><div class="prospect-grid">'+prospects.map(a=>{const opportunity=DEMO_SF_OPPORTUNITIES.find(o=>o.account===a.id);return '<article class="panel prospect-card"><div class="section-head">'+badge('Prospect','blue')+'<span class="fineprint">'+esc(a.region)+'</span></div><h3><a href="#accounts/'+a.id+'">'+esc(a.name)+'</a></h3><p>'+esc(a.city)+'</p><dl><dt>Why it’s a fit</dt><dd>'+esc(a.opportunity)+'.</dd><dt>Buyer contact · demo</dt><dd>'+esc(a.contact)+' · '+esc(a.role)+'</dd><dt>Potential opportunity</dt><dd>'+(opportunity?money(opportunity.value)+' opening assortment · illustrative pipeline value':esc(a.potential||'Pre-roll introduction · value not estimated'))+'</dd><dt>Next move</dt><dd>'+esc(a.action)+'</dd></dl><div class="briefing-actions"><button class="primary" data-prep="'+a.id+'">Learn More →</button></div></article>';}).join('')+'</div></section>';}

function prospectsPage(){return prospectViews('prospects')+hotProspects().replace("<h2>Hot Prospects</h2>","<h1>Hot Prospects</h1><p class=\"page-subhead\">New doors to open. The right conversations to start.</p>");}


function appointmentSlider(){return `<section class="appointment-carousel" aria-label="Today’s appointments" aria-roledescription="carousel"><div class="appointment-carousel-top"><span class="card-kicker">UP NEXT · TODAY’S APPOINTMENTS</span><div><button type="button" data-slide-step="-1" aria-label="Previous appointment">←</button><button type="button" data-slide-step="1" aria-label="Next appointment">→</button></div></div><div class="appointment-track" id="appointment-track" tabindex="0" aria-label="Scroll through appointments">${STOPS.map((s,i)=>{const a=ACCOUNTS.find(a=>a.id===s.id);return `<a class="next-card appointment-slide" href="#appointment/${s.id}" aria-label="View appointment with ${esc(a.name)} at ${s.time}"><div class="next-top"><span class="card-kicker">${i===0?'FIRST STOP':'LATER TODAY'}</span><span class="time-tag">${s.time}</span></div><div class="stop-number">${s.number}<span>/ ${String(STOPS.length).padStart(2,'0')}</span></div><h2>${esc(a.name)}</h2><p>${esc(s.focus)}</p><div class="buyer-line"><span class="buyer-avatar">${a.contact.split(' ').map(w=>w[0]).join('')}</span><span><strong>${esc(a.contact)}</strong><small>${esc(a.city)}</small></span></div><div class="next-insight"><span>BEFORE YOU WALK IN</span><p>${esc(a.opportunity)}.</p></div><span class="primary prep-button">View appointment ↗</span><p class="card-footnote">${i+1} of ${STOPS.length} · Swipe or use the arrows · Demo</p></a>`}).join('')}</div></section>`;}
function appointmentPage(id){
 const stop=STOPS.find(s=>s.id===id),a=ACCOUNTS.find(a=>a.id===id);if(!stop||!a)return missing();
 const recap=debriefs.find(d=>d.account===id);
 const recent=accountHistory(id).slice(0,3);
 return `<div class="appointment-page"><a href="#home" class="text-button">← My Day Today</a>${heading('YOUR APPOINTMENT · SEPTEMBER 25, 2026',a.name,stop.focus)}<section class="panel appointment-summary"><p class="card-kicker">GOOGLE CALENDAR · SAMPLE APPOINTMENT · NOT SYNCED</p><h2>${calendarMeta(id)}</h2><div class="detail-meta"><div><span>Meeting with</span><b>${esc(a.contact)}</b><span>${esc(a.role)} · synthetic contact</span></div><div><span>Location</span><b>${id==='hudson'?'Video call · meeting link not configured':esc(a.city)}</b></div><div><span>Contact email</span><b>${esc(accountEmail(id)||'No email saved')}</b></div><div><span>Visit status</span><b>${recap?'Recap saved':'Planned · outcome not recorded'}</b></div></div></section><section class="panel"><h2>Before the meeting</h2><p>${esc(a.opportunity)}.</p><p><strong>Next move:</strong> ${esc(a.action)}</p><div class="briefing-actions"><button class="primary" data-prep="${id}">Catch me up ↗</button><button class="secondary" data-note="${id}">Log activity</button></div></section><section class="panel"><div class="section-head"><h2>Recent account notes</h2><a href="#pastnotes/${id}">My Past Notes →</a></div>${recent.length?recent.map(noteDisclosure).join(''):'<p>No notes saved for this account yet.</p>'}</section>${recap?`<section class="panel"><h2>This visit’s recap</h2><p>${esc(recap.outcome)}</p><p><strong>Next:</strong> ${esc(recap.action)}</p></section>`:''}<p class="fineprint">Fictional demo appointment and account information.</p></div>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-slide-step]');if(!b)return;const track=document.getElementById('appointment-track');if(!track)return;track.scrollBy({left:Number(b.dataset.slideStep)*track.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});

function brandCreatives(){return [
{id:'brand-logo',channel:'Brand identity',title:'Betty’s Eddies logo',file:'Betty’s Eddieslogo.webp'},
{id:'love-art',channel:'Product graphics',title:'Love Machine artwork',file:'love-machine.webp'},
{id:'stadank-art',channel:'Product graphics',title:'StaDankOHHH artwork',file:'stahdank.webp'},
{id:'drooler-art',channel:'Product graphics',title:'Drooler artwork',file:'drooler.webp'},
{id:'lowrider-art',channel:'Product graphics',title:'Lowrider artwork',file:'lowrider.webp'},
{id:'yesca-art',channel:'Product graphics',title:'YesCa artwork',file:'yesca.webp'}
].map(c=>({...c,official:true,url:'https://www.bettyseddies.com/wp-content/uploads/2025/04/'+c.file,format:'Official website graphic · WebP',date:'Sep 26, 2026'}));}
function creativeVisual(c){if(c.official)return `<div class="official-creative-art"><img src="${c.url}" alt="${esc(c.title)}" loading="lazy" referrerpolicy="no-referrer"></div>`;return `<div class="creative-art creative-${c.id}" style="--asset-color:${c.color}"><span>Betty’s Eddies<br>CONCEPT STUDIO</span><strong>${c.headline}</strong><p>${c.sub}</p><small>DEMO CREATIVE · NOT APPROVED FOR PUBLICATION</small></div>`;}
function brandPage(){return `${heading('THE BRAND TOOLKIT','Products & Sales Tools','Know the lineup. Find the creative. Bring the brand to your next stop.')}<nav class="brand-section-nav" aria-label="Products and brand sections"><button class="primary" data-brand-section="product-catalog">Product</button><button class="secondary" data-brand-section="brand-materials">Brand</button></nav><p class="notice">Catalog images and descriptions are sourced from the official Betty’s Eddies Cannabis website. New York availability, pricing, and inventory are not verified. Creative graphics below are also sourced from the official website; publication approval is not verified.</p>${officialProductCatalog()}<section class="brand-library" id="brand-materials" tabindex="-1" aria-label="Brand creative library"><div class="rep-section-title"><div><span class="card-kicker">OFFICIAL WEBSITE ASSETS · REVIEWED SEPTEMBER 2026</span><h2>Creative library</h2></div></div><p>Public brand artwork, ready to preview and share as source links.</p><p class="notice">For approved social campaigns, in-store displays, and production files: <a href="https://Betty’s Eddies.lingoapp.com/" target="_blank" rel="noopener">Open official brand portal ↗</a> · Password required.</p>${assetEmailAccountPicker("creative-account")}<div class="creative-filters" role="group" aria-label="Filter creative content">${['All content','Brand identity','Product graphics'].map((label,i)=>`<button class="${i?'secondary':'primary'}" data-creative-filter="${label}" aria-pressed="${!i}">${label}</button>`).join('')}</div><div class="brand-creative-grid">${brandCreatives().map(c=>`<article class="brand-creative" data-creative-channel="${c.channel}">${creativeVisual(c)}<div class="brand-card-copy"><span class="card-kicker">${c.channel}</span><h3>${c.title}</h3><p>${c.format}<br>Source checked ${c.date}</p><div class="asset-actions" role="group" aria-label="Creative actions"><button class="secondary" data-preview-creative="${c.id}">Preview</button><button class="secondary" data-download-creative="${c.id}" title="Open the original image to save it">Download</button><button class="primary" data-send-creative="${c.id}" title="Prepare an email with this creative">Send</button></div></div></article>`).join('')}</div><p class="fineprint">Images © respective owner. These are public website graphics, not verified social templates or print-ready files. Original publication dates are unavailable; this is a sourced snapshot, not a live feed.</p></section>`;}
function brandCreativeSvg(c){
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${c.width}" height="${c.height}" viewBox="0 0 1080 1080"><rect width="1080" height="1080" fill="${c.color}"/><g fill="#FFFDE9" font-family="Arial, sans-serif"><text x="80" y="130" font-size="32">Betty’s Eddies · CONCEPT STUDIO</text><text x="80" y="440" font-size="66" font-weight="bold">${esc(c.headline)}</text><text x="80" y="570" font-size="32">${esc(c.sub)}</text><text x="80" y="940" font-size="20">DEMO CREATIVE · NOT APPROVED FOR PUBLICATION</text></g></svg>`;
 return svg;
}
function downloadBrandCreative(c){
 if(c.official){window.open(c.url,'_blank','noopener,noreferrer');return;}
 const url=URL.createObjectURL(new Blob([brandCreativeSvg(c)],{type:'image/svg+xml'}));const link=document.createElement('a');link.href=url;link.download='QuickHits-demo-'+c.id+'.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
document.addEventListener('click',e=>{
 const filter=e.target.closest('[data-creative-filter]');if(filter){document.querySelectorAll('[data-creative-filter]').forEach(b=>{const active=b===filter;b.classList.toggle('primary',active);b.classList.toggle('secondary',!active);b.setAttribute('aria-pressed',String(active));});document.querySelectorAll('[data-creative-channel]').forEach(card=>{card.hidden=filter.dataset.creativeFilter!=='All content'&&card.dataset.creativeChannel!==filter.dataset.creativeFilter;});}
 const preview=e.target.closest('[data-preview-creative]');if(preview){const c=brandCreatives().find(c=>c.id===preview.dataset.previewCreative);if(c){document.getElementById('creative-preview-title').textContent=c.title;document.getElementById('creative-preview-content').innerHTML=creativeVisual(c);document.querySelector('#creative-preview .fineprint').textContent='Official website graphic · Image © respective owner · Publication approval not verified.';document.getElementById('creative-preview').showModal();}}
 if(e.target.closest('#close-creative-preview'))document.getElementById('creative-preview').close();
 const download=e.target.closest('[data-download-creative]');if(download){const c=brandCreatives().find(c=>c.id===download.dataset.downloadCreative);if(c)downloadBrandCreative(c);}
});

function prospectViews(view){return `<nav class="account-views" aria-label="Prospecting tools"><a href="#prospects" class="${view==='prospects'?'active':''}" ${view==='prospects'?'aria-current="page"':''}>Hot Prospects</a><a href="#products" class="${view==='products'?'active':''}" ${view==='products'?'aria-current="page"':''}>Competition Check</a></nav>`;}

// Team workspace: local prototype records, not a shared multi-user service.
function teamStored(key){try{const rows=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(rows)?rows:[];}catch{return [];}}
let teamRepFilter='all',teamTypeFilter='all';
function teamReps(){return [{id:'harry',name:'Harry',territory:'New York',source:'Current demo rep'},{id:'maya',name:'Sturgill',territory:'Hudson Valley',source:'Synthetic rep'},{id:'jules',name:'Bonnie',territory:'Western NY',source:'Synthetic rep'},...teamStored('quickhits-team-reps-v1')];}
function teamActivity(){return [
 ...notes.map(n=>({...n,rep:'harry',source:n.local?'Saved in this browser':'Synthetic sample'})),
 {id:'sample-maya',rep:'maya',account:'hudson',type:'Call',text:'Discussed category priorities with the buyer. Next step: prepare an introductory assortment for review.',date:'2026-10-06T15:00:00-04:00',source:'Synthetic sample'},
 {id:'sample-jules',rep:'jules',account:'buffalo',type:'Store visit',text:'Reviewed the demo flower assortment with store staff. Next step: confirm a product education session.',date:'2026-10-06T11:00:00-04:00',source:'Synthetic sample'},
 ...teamStored('quickhits-team-activity-v1')].sort((a,b)=>new Date(b.date)-new Date(a.date));}
function teamPage(){
 const reps=teamReps(),activities=teamActivity(),shown=activities.filter(n=>(teamRepFilter==='all'||n.rep===teamRepFilter)&&(teamTypeFilter==='all'||n.type===teamTypeFilter));
 const selected=reps.find(r=>r.id===teamRepFilter);const tasks=followupRows().filter(f=>!selected||f.owner===selected.name);
 const opportunities=teamRepFilter==='all'||teamRepFilter==='harry'?DEMO_SF_OPPORTUNITIES:[];
 return `<section class="team-brand-hero"><div><span class="card-kicker">Betty’s Eddies · THE WHOLE CREW</span><h1>Team<br>Overview<span class="red-dot">.</span></h1><p>Every rep. Every conversation.<br>The next move, all in one place.</p></div><div class="team-brand-stamp"><span>NEW YORK FIELD TEAM</span><strong>${reps.length}</strong><b>REPS ON THE ROSTER</b><small>Demo workspace · Harry + the crew</small></div></section><p class="notice">Demo team dashboard · Sample reps plus records saved in this browser. Adding a rep creates a local profile, not a login. Cross-device activity and CRM sync are not connected.</p><div class="toolbar"><label>Rep<select id="team-rep"><option value="all">All reps</option>${reps.map(r=>`<option value="${esc(r.id)}" ${teamRepFilter===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>Activity type<select id="team-type">${['all','Store visit','Call','Follow-up','Comment'].map(t=>`<option value="${t}" ${teamTypeFilter===t?'selected':''}>${t==='all'?'All activity':t}</option>`).join('')}</select></label><button class="secondary" id="team-refresh">Refresh activity</button></div><div class="team-metrics"><div><strong>${selected?1:reps.length}</strong><span>Reps in view</span></div><div><strong>${shown.length}</strong><span>Activity records · all dates</span></div><div><strong>${tasks.filter(t=>!t.done).length}</strong><span>Open follow-ups</span></div><div><strong>${money(opportunities.reduce((n,o)=>n+o.value,0))}</strong><span>Demo pipeline · unweighted</span></div></div><section class="panel"><h2>The crew</h2><div class="team-roster">${reps.map(r=>`<button class="team-rep-card" data-team-rep="${esc(r.id)}"><strong>${esc(r.name)}</strong><span>${esc(r.territory)}</span><small>${activities.filter(n=>n.rep===r.id).length} activity records · ${esc(r.source)}</small></button>`).join('')}</div><details class="team-add"><summary>Add a rep</summary><form id="team-add-rep"><label>Name<input name="name" required maxlength="80"></label><label>Territory<input name="territory" required maxlength="100"></label><button class="primary">Add rep</button></form></details></section>${managerOpportunityView()}<section class="panel"><div class="section-head"><h2>All rep activity</h2><span class="fineprint">Newest first · Rep filter + activity filter</span></div>${shown.length?`<div class="table-wrap"><table><thead><tr><th>When / rep</th><th>Account / activity</th><th>What happened</th></tr></thead><tbody>${shown.map(n=>`<tr><td>${formatDate(n.date)}<br><strong>${esc(reps.find(r=>r.id===n.rep)?.name||'Unknown rep')}</strong></td><td><a href="#accounts/${esc(n.account)}">${esc(ACCOUNTS.find(a=>a.id===n.account)?.name||n.account)}</a><br>${esc(n.type)}</td><td>${esc(n.text)}<br><small>${esc(n.source)}</small></td></tr>`).join('')}</tbody></table></div>`:'<p>No activity for these filters yet.</p>'}<details class="team-add"><summary>Log rep activity</summary><form id="team-log-activity"><label>Rep<select name="rep">${reps.map(r=>`<option value="${esc(r.id)}" ${r.id===teamRepFilter?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>Account<select name="account">${ACCOUNTS.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><label>Activity<select name="type"><option>Store visit</option><option>Call</option><option>Follow-up</option><option>Comment</option></select></label><label>What happened / next step<textarea name="text" required maxlength="1500" rows="3"></textarea></label><button class="primary">Save activity</button></form></details></section><div class="team-bottom"><section class="panel"><h2>Follow-ups & team requests</h2><p class="fineprint">Filtered by task owner. Team requests without an assigned owner appear in All reps.</p>${tasks.length?tasks.map(t=>`<div class="team-summary-row"><strong>${esc(t.action)}</strong><p>${esc(t.owner)} · ${esc(ACCOUNTS.find(a=>a.id===t.account)?.name||t.account)}<br>Due ${esc(t.due||'not set')} · ${t.done?'Done':t.waiting?'Waiting on team':'Open'}</p></div>`).join(''):'<p>No assigned follow-ups yet.</p>'}<a href="#followups">Manage follow-ups →</a></section><section class="panel"><h2>Pipeline & reports</h2><p class="fineprint">Current pipeline records belong to Harry. No opportunity is a confirmed order.</p>${opportunities.map(o=>`<div class="team-summary-row"><strong>${esc(o.title)} · ${money(o.value)}</strong><p>${esc(o.stage)} · ${esc(ACCOUNTS.find(a=>a.id===o.account)?.name)}</p></div>`).join('')||'<p>No pipeline records assigned to this rep.</p>'}<p>${teamRepFilter==='all'||teamRepFilter==='harry'?debriefs.length:0} saved visit recaps for this view.</p><a href="#report">Harry’s daily report →</a><p><a href="#accounts">All accounts →</a> · <a href="#brand">Brand toolkit →</a></p><p class="fineprint">Meeting photos remain linked to their account’s meeting notes. Email delivery is not tracked.</p></section></div>`;
}
