 if(!['team-add-rep','team-log-activity'].includes(e.target.id))return;e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));
 try{if(form.id==='team-add-rep'){if(!data.name.trim()||!data.territory.trim())return;const reps=teamStored('quickhits-team-reps-v1');if(teamReps().some(r=>r.name.toLowerCase()===data.name.trim().toLowerCase())){toast('That rep is already listed.');return;}reps.push({id:crypto.randomUUID(),name:data.name.trim(),territory:data.territory.trim(),source:'Local profile'});localStorage.setItem('quickhits-team-reps-v1',JSON.stringify(reps));}else{if(!data.text.trim())return;const rows=teamStored('quickhits-team-activity-v1');rows.push({...data,id:crypto.randomUUID(),date:new Date().toISOString(),source:'Saved in this browser'});localStorage.setItem('quickhits-team-activity-v1',JSON.stringify(rows));teamRepFilter=data.rep;teamTypeFilter='all';}render();toast('Saved on this browser.');}catch{toast('Could not save. Browser storage may be full.');}
