function officialProductCatalog(){return `<section class="brand-catalog" id="product-catalog" tabindex="-1" aria-label="Product catalog"><div class="rep-section-title"><div><span class="card-kicker">FROM THE OFFICIAL BRAND SITE</span><h2>Product catalog</h2></div><span>6 sourced product lines</span></div>${assetEmailAccountPicker("product-account")}<div class="brand-product-grid">${officialCatalogItems().map((p,i)=>`<article class="brand-product"><div class="catalog-art official-product-art"><img src="https://www.bettyseddies.com/wp-content/uploads/2025/04/${p.image}" alt="${esc(p.name)} — official Betty’s Eddies product image" loading="lazy" referrerpolicy="no-referrer"><span class="image-unavailable" hidden>Image unavailable · View the official source below</span></div><div class="brand-card-copy"><span class="card-kicker">${esc(p.category)}</span><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><details><summary>Product details & source</summary><p>Brand-listed formats: ${esc(p.formats)}.</p><p class="fineprint">Packaging shown may represent one format. Formats and formulations can vary by market. No batch potency, stock, or New York distribution is confirmed here.</p></details><p><a href="https://www.bettyseddies.com/" target="_blank" rel="noopener">Official product source ↗</a></p><small class="fineprint">Source checked Sep 26, 2026 · Image © respective owner</small><div class="asset-actions" role="group" aria-label="Product actions"><button class="secondary" data-product-preview="${i}">Preview</button><button class="secondary" data-product-original="${i}" title="Open the original image to save it">Download</button><button class="primary" data-product-send="${i}" title="Prepare an email with this product">Send</button></div></div></article>`).join('')}</div><p class="fineprint">Images load from the official brand website and require an internet connection. Competition Check uses explicitly illustrative competitor rankings.</p></section>`;}
document.addEventListener('error',e=>{if(e.target.matches?.('.official-product-art img')){e.target.hidden=true;e.target.nextElementSibling.hidden=false;}},true);

