 if(b.hasAttribute('data-product-preview')){document.getElementById('creative-preview-title').textContent=p.name;document.getElementById('creative-preview-content').innerHTML=creativeVisual({official:true,url,title:p.name});document.querySelector('#creative-preview .fineprint').textContent='Official product image · Image © respective owner · New York availability not verified.';document.getElementById('creative-preview').showModal();return;}
